/**
 * med-knowledge.json invariants (G2-34).
 *
 * The file's 79 medications used to carry a single file-level "Sourced from FDA
 * drug labels (DailyMed) and MedlinePlus" and nothing per entry — no citation,
 * no version, no date, all arriving in one commit. Apple Guideline 1.4.1 wants
 * disclosed methodology behind health accuracy claims, and FDA's enforcement
 * discretion under the 2022 mobile medical applications policy (Appendix B,
 * Example 18) turns on the information coming from FDA-approved labeling.
 *
 * Provenance is now generated by scripts/fetch-med-provenance.mjs. This asserts
 * it is still there and still coherent, so the next medication somebody adds
 * cannot arrive uncited — which is how the file got into this state.
 */

const assert = require('node:assert');
const { readFileSync } = require('node:fs');

let failures = 0;
function check(name, fn) {
  try {
    fn();
    console.log(`  ok    ${name}`);
  } catch (err) {
    failures += 1;
    console.log(`  FAIL  ${name}\n        ${err.message}`);
  }
}

const doc = JSON.parse(readFileSync('src/lib/med-knowledge.json', 'utf8'));
const meds = doc.medications;
const names = Object.keys(meds);

console.log(`med-knowledge.json — ${names.length} medications\n`);

check('every medication carries a provenance block', () => {
  const missing = names.filter((n) => !meds[n].provenance);
  assert.deepStrictEqual(missing, [], `uncited: ${missing.join(', ')}`);
});

check('every provenance block has the fields a reader needs to check it', () => {
  const required = ['rxcui', 'labelSource', 'labels', 'labelCount', 'retrieved', 'attests'];
  const bad = [];
  for (const n of names) {
    for (const f of required) {
      if (meds[n].provenance?.[f] === undefined) bad.push(`${n}.${f}`);
    }
  }
  assert.deepStrictEqual(bad, [], `incomplete: ${bad.join(', ')}`);
});

check('every rxcui is a plain numeric id', () => {
  const bad = names.filter((n) => !/^\d+$/.test(String(meds[n].provenance.rxcui)));
  assert.deepStrictEqual(bad, [], `malformed rxcui: ${bad.join(', ')}`);
});

// The check that caught a real bug. The provenance script originally used
// RxNorm's normalized search alone, which resolved `omeprazole` to 283742 —
// a concept RxNorm calls `esomeprazole`, a different medicine with a different
// label. Two names sharing one concept id is the signature of that mistake, and
// a citation pointing at the wrong drug is worse than none because it looks
// like diligence.
check('no two medications share one RxNorm concept id', () => {
  const byRxcui = new Map();
  for (const n of names) {
    const rx = String(meds[n].provenance.rxcui);
    byRxcui.set(rx, [...(byRxcui.get(rx) ?? []), n]);
  }
  const collisions = [...byRxcui.entries()]
    .filter(([, ns]) => ns.length > 1)
    .map(([rx, ns]) => `${rx}: ${ns.join(' + ')}`);
  assert.deepStrictEqual(collisions, [], `collisions: ${collisions.join('; ')}`);
});

check('every medication has at least one FDA label behind it', () => {
  const bad = names.filter((n) => !(meds[n].provenance.labelCount > 0));
  assert.deepStrictEqual(bad, [], `no labels: ${bad.join(', ')}`);
});

// The boundary is the honest part of the claim, and it has to survive editing.
// Without it the file reads as though each symptom string were label-verified,
// which is not what was done and not what is claimed.
check('every entry restates what its citation does NOT attest', () => {
  const bad = names.filter((n) => !/NOT that each listed symptom/.test(meds[n].provenance.attests));
  assert.deepStrictEqual(bad, [], `missing the limit: ${bad.join(', ')}`);
});

check('the file header states the provenance method and its limit', () => {
  assert.match(doc.$comment, /fetch-med-provenance/, 'header does not name the generator');
  assert.match(doc.$comment, /does NOT/, 'header does not state the limit of the citation');
});

// G1-23: the app describes, it does not instruct. "Call the doctor today" is a
// directive, and this file's own vocabulary is what the UI copy is built from.
check('no symptom string is phrased as an instruction', () => {
  const directive = /^(call|go to|take|stop|start|give|visit|dial)\b/i;
  const bad = [];
  for (const n of names) {
    for (const list of ['common', 'urgent']) {
      for (const s of meds[n][list] ?? []) {
        if (directive.test(s)) bad.push(`${n}.${list}: "${s}"`);
      }
    }
  }
  assert.deepStrictEqual(bad, [], `directives: ${bad.join(', ')}`);
});

console.log(
  failures === 0
    ? '\nPASS: every medication is cited, and the citation says what it does not cover'
    : `\nFAIL: ${failures} check(s)`,
);
process.exit(failures === 0 ? 0 : 1);
